parameters.jsCode:
// Formularanbieter liefern die Felder mal unter body, mal direkt im Item.
// Erst normalisieren, sonst prueft der naechste Schritt gegen undefined und
// laesst jede Anfrage durchfallen.
const raus = [];
for (const eintrag of $input.all()) {
  const d = eintrag.json.body ?? eintrag.json;
  const email = String(d.email ?? '').trim().toLowerCase();
  const name = String(d.name ?? '').trim();
  const nachricht = String(d.nachricht ?? d.message ?? '').trim();

  // Bewusst nur ein grober Formcheck: eine strenge RFC-Regex verwirft mehr
  // gueltige Adressen (Umlautdomains, lange TLDs) als sie Tippfehler faengt.
  const mailOk = /^[^@\s]+@[^@\s]+\.[a-zA-Z]{2,}$/.test(email);

  const fehlend = [];
  if (!name) fehlend.push('Name');
  if (!mailOk) fehlend.push('E-Mail');
  if (!nachricht) fehlend.push('Nachricht');

  raus.push({
    json: {
      name,
      email,
      // Telefonnummern kommen in jeder denkbaren Schreibweise an; fuer den
      // Dublettenabgleich und das CRM reicht die reine Ziffernfolge.
      telefon: String(d.telefon ?? d.phone ?? '').replace(/[^0-9+]/g, ''),
      firma: String(d.firma ?? d.company ?? '').trim(),
      nachricht,
      quelle: String(d.quelle ?? 'Webformular').trim(),
      eingegangen_am: new Date().toLocaleDateString('de-DE'),
      fehlende_felder: fehlend,
      vollstaendig: fehlend.length === 0
    }
  });
}
return raus;

